"ahiram":{"n":"亞希蘭","r":"便雅憫的兒子","m":"我的兄弟是崇高的（受尊崇的）","s":"便雅憫的兒子，亞希蘭家族的祖先；看來也叫以希和亞哈拉。","aka":["以希","亞哈拉","亞赫"],"src":{"d":"1200000164","t":"亞希蘭"}},
"ard":{"n":"亞德","r":"便雅憫人；亞德家族的祖先","s":"名列進入埃及的雅各家人之中；看來是便雅憫通過比拉所生的孫子，亞德家族的首領。","aka":["亞達珥"],"src":{"d":"1200000351","t":"亞德"}},
"areli":{"n":"亞列利","r":"迦得的兒子；亞列利家族的首領","s":"迦得的第七個兒子，跟雅各一起進入埃及，成為亞列利家族的首領。","src":{"d":"1200000354","t":"亞列利"}},
"arod":{"n":"亞律","r":"迦得的兒子；亞律家族的首領","s":"迦得的第六個兒子，跟雅各一起來到埃及，是亞律家族的首領。","aka":["亞律底"],"src":{"d":"1200000381","t":"亞律"}},
