"bela-a":{"n":"比拉","r":"便雅憫的長子","s":"便雅憫的長子，跟雅各一起去了埃及，是比拉家族的祖先。","src":{"d":"1200000622","t":"比拉"}},
"beriah-1":{"n":"比利亞","r":"亞設的兒子","m":"遭遇災禍","s":"亞設的兒子中名列第四，跟雅各一家進入埃及；希別和瑪結的父親，比利亞家族的祖先。","src":{"d":"1200000653","t":"比利亞"}},
"carmi-1":{"n":"卡米","r":"呂便的兒子","m":"可能指修剪葡萄樹的人","s":"呂便的兒子，跟雅各一家來到埃及；卡米家族的祖先。","src":{"d":"1200000894","t":"卡米"}},
"elon-2":{"n":"以倫","r":"西布倫的兒子","m":"可能指大樹","s":"西布倫的次子，跟雅各一起去了埃及；以倫家族的首領。","src":{"d":"1200001333","t":"以倫"}},
"eri":{"n":"以里","r":"迦得的兒子","m":"醒來的人","s":"迦得的第五個兒子，以里家族的祖先。","src":{"d":"1200001415","t":"以里"}},
"ezbon-1":{"n":"以斯本","r":"迦得的兒子","s":"迦得的兒子，雅各的孫子；看來也叫奧斯尼，是奧斯尼家族的祖先。","aka":["奧斯尼"],"src":{"d":"1200001468","t":"以斯本"}},
