"gershon":{"n":"革順","r":"利未的兒子；革順人的祖先","m":"在那裡寄居的外人","s":"利未三個兒子中名列第一，他的後代組成了利未人的革順支系；有些經文的英文作Gershom。","aka":["革順"],"src":{"d":"1200001663","t":"革順"}},
"guni-1":{"n":"古尼","r":"拿弗他利的兒子","s":"拿弗他利的次子，屬於在埃及的雅各家人；古尼家族的祖先。","src":{"d":"1200001783","t":"古尼"}},
"haggi":{"n":"哈基","r":"迦得的兒子","m":"在節期出生的","s":"迦得的次子，雅各的孫子，哈基家族的祖先。","src":{"d":"1200001814","t":"哈基"}},
