"gedor-1":{"n":"基多","r":"便雅憫人，掃羅的叔祖","m":"石牆","s":"基遍的便雅憫人，耶利的兒子；他是掃羅祖父的兄弟，因此是掃羅王的叔祖。","src":{"d":"1200001639","t":"基突"}},
"hanan-1":{"n":"哈南","r":"便雅憫人，沙沙克的兒子","m":"施恩；仁慈","s":"便雅憫人，名列沙沙克的兒子。","rn":{"father":["沙沙克"]},"src":{"d":"1200001850","t":"哈南"}},
