"shimei-5":{"n":"示每","r":"有九個兒子的便雅憫人","m":"可能是示瑪雅的簡稱，意思是耶和華已經聽見","s":"便雅憫人，他的九個兒子在耶路撒冷做宗族首領；看來就是亞雅崙的示瑪。","aka":["示瑪"],"src":{"d":"1200004047","t":"示每"}},
"sismai":{"n":"西斯邁","r":"猶大人，耶拉篾的後代","s":"以利亞薩的兒子，沙龍的父親，屬於示珊的家系；可能生活在士師時代。","src":{"d":"1200004148","t":"西斯邁"}},
"tola-1b":{"n":"陀拉","r":"以色列的士師","m":"深紅色（猩紅色）的布","s":"以薩迦人普瓦的兒子，審判以色列23年；他住在以法蓮山區，死後也葬在那裡。","src":{"d":"1200004444","t":"陀拉"}},
"zebul":{"n":"西布勒","r":"示劍的官員","m":"容忍；或，可能指：高處的居所","s":"亞比米勒委派管理示劍的官員；他向亞比米勒報告迦阿勒的叛亂，激迦阿勒出城作戰，然後把迦阿勒和他的兄弟趕出城去。","src":{"d":"1200004678","t":"西布勒"}},
"zecher":{"n":"撒迦","r":"便雅憫人，耶利的兒子","m":"撒迦利亞的簡稱","s":"耶利的後代，耶利被稱為基遍的「父親」；在平行的名單中，他的名字寫作撒迦利亞，撒迦是它的簡稱。","aka":["撒迦利亞"],"src":{"d":"1200004683","t":"撒迦"}},
"zur-2":{"n":"祖珥","r":"便雅憫人，耶利的兒子","m":"磐石","s":"便雅憫人，耶利的兒子，看來是掃羅王的祖父尼珥的兄弟。","src":{"d":"1200004771","t":"祖珥"}},
