"goliath":{"n":"歌利亞","r":"非利士人的勇士","m":"—","s":"迦特的巨人，身高約2.9米（9.5英尺），一連40天向以色列軍隊挑戰，最後被年輕的大衛用投石器的石頭打死。","note":"出生年份是假定的；在大衛受膏後不久死去。","e":["向以色列的軍隊挑戰","被大衛殺死"]},
"barzillai-2":{"n":"巴西萊","r":"支持大衛的基列人","m":"屬於鐵","s":"住在羅基琳、富有的基列老人。押沙龍叛亂時，他供應大衛所需；他80歲時婉拒住進王宮，讓金罕代替他去。","src":{"d":"1200000572","t":"巴西萊"}},
"dodo-2":{"n":"杜多","r":"亞合人，以利亞撒的父親","m":"親愛的","s":"便雅憫族的亞合人，他的兒子以利亞撒是大衛的三大勇士之一。他名叫杜代時，負責統領第二個月輪值的軍隊。","aka":["杜代"],"src":{"d":"1200001207","t":"杜多"}},
"ishvi-2":{"n":"伊施韋","r":"掃羅王的兒子","m":"被造得相等","s":"掃羅王的兒子之一。","src":{"d":"1200002223","t":"伊施韋"}},
"maacah-6":{"n":"瑪迦","r":"哈南的父親","m":"可能源自意思是「擠壓」的詞根","s":"哈南的父親或祖先；哈南是大衛軍中的勇士之一。","src":{"d":"1200002803","t":"瑪迦"}},
"merab":{"n":"梅拉","r":"掃羅的大女兒","m":"源自意思是「變多（豐盛）」的詞根","s":"掃羅本來要把她許配給大衛，後來卻把她嫁給了米何拉人亞得列。","src":{"d":"1200002987","t":"梅拉"}},
"shammah-2":{"n":"沙瑪","r":"大衛的哥哥","s":"耶西的第三個兒子，沒有被撒母耳選中。他在掃羅的軍隊裡對抗歌利亞；他的兒子約拿單殺了一個巨人。","aka":["示米亞"],"src":{"d":"1200003942","t":"沙瑪"}},
"shimea-3":{"n":"示米亞","r":"大衛的哥哥","m":"可能是示瑪雅的簡稱，意思是耶和華已經聽見（垂聽）","s":"耶西的第三個兒子，大衛的哥哥；也叫沙瑪和示米亞。","aka":["沙瑪","示米亞"],"src":{"d":"1200004042","t":"示米阿"}},
"uriah-1":{"n":"烏利亞","r":"赫提人戰士，拔示巴的丈夫","m":"我的光是耶和華","s":"大衛手下的外族戰士，可能是歸信者，娶了拔示巴。他忠於軍隊，不肯回家；後來大衛通過約押安排他在拉巴戰死。","src":{"d":"1200004521","t":"烏利亞"}},
"zeruiah":{"n":"洗魯雅","r":"約押的母親","m":"香脂","s":"大衛的姊妹或同父異母的姊妹，戰士約押、亞比篩和亞撒黑的母親；她可能比大衛年長很多。","src":{"d":"1200004717","t":"洗魯雅"}},
"ahimelech-1":{"n":"亞希米勒","r":"挪伯的大祭司","s":"亞希突的兒子，不知情下幫助了逃亡的大衛。掃羅叫多益殺了他和挪伯的祭司，只有亞比亞他逃脫。","src":{"d":"1200000158","t":"亞希米勒"}},
