"ebed-melech":{"n":"以伯米勒","r":"救了耶利米的埃塞俄比亞宦官","m":"王的僕人","s":"在西底家王的宮裡服務，他勇敢地為耶利米求情，把他從滿是泥濘的蓄水池拉上來；耶和華應許他會在耶路撒冷陷落時存活。","src":{"d":"1200001247","t":"以伯米勒"}},
"ishmael-5":{"n":"以實瑪利","r":"刺殺基大利的人","m":"上帝聽見","s":"尼探雅的兒子，屬於王族。耶路撒冷陷落後，他與亞捫王密謀，殺了總督基大利，擄走一些人，然後逃到亞捫。","src":{"d":"1200002215","t":"以實瑪利"}},
"jaazaniah-4":{"n":"雅撒尼亞","r":"猶大的軍隊首領","m":"耶和華已經側耳聽","s":"猶大的一個軍隊首領，支持總督基大利，幫忙救回被以實瑪利擄走的人，後來不聽耶利米的勸告，帶領餘下的人去埃及。","aka":["耶撒尼亞"],"src":{"d":"1200002264","t":"雅撒尼亞"}},
